        payload: { ...base, success: true as const },
      } as AgenticEvent)
    } else {
      this.eventBus.emit({
        type: "step.failed",
        payload: {
          ...base,
          error: error ?? output,
          errorCategory: "unknown" as const,
        },
      } as AgenticEvent)
    }

    this._currentResult = undefined
    return result
  }

  /**
   * Relay delegation result dari agentic_delegate.
   */
  relayDelegation(
    sessionId: string,
    taskId: string,
    role: string,
    success: boolean,
